using UnityEditor; using UnityEditor.SceneManagement; using UnityEngine;
namespace DungeonRoguelite.Editor { [InitializeOnLoad] public static class D4WaveTransitionRunner { static D4WaveTransitionRunner(){ EditorApplication.playModeStateChanged += s => { if(s==PlayModeStateChange.EnteredPlayMode && SessionState.GetBool("D4WavePending",false)){ SessionState.EraseBool("D4WavePending"); new GameObject("D4WaveTransitionVerifier").AddComponent<Tests.D4WaveTransitionVerifier>(); }};} public static void Run(){ EditorSceneManager.NewScene(NewSceneSetup.EmptyScene,NewSceneMode.Single); SessionState.SetBool("D4WavePending",true); EditorApplication.EnterPlaymode(); } } }
